    version: 1,
    ...(args.title ? { title: displayValue(args.title, TITLE_MAX_LENGTH) } : {}),
    ...(args.tone ? { tone: args.tone } : {}),
    blocks: sanitizeBlocks(args.blocks),
    actions: [],
