				) : null}
			</div>
		);
	}
	if (!isRecord(value))
		return <span className="text-sm">Unsupported value</span>;
	if (looksLikeEvent(value))
		return <EventView event={value} openLink={openLink} />;
	if (looksLikeEntity(value))
		return <EntityView entity={value} openLink={openLink} />;
	return (
		<dl className="grid gap-1.5">
			{Object.entries(value).map(([key, inner]) => (
				<div
					key={key}
					className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
				>
					<dt className="break-words font-medium text-muted-foreground">
						{humanize(key)}
					</dt>
					<dd className="min-w-0">
						<ValueView value={inner} openLink={openLink} depth={depth + 1} />
					</dd>
				</div>
			))}
		</dl>
	);
};

