import { createElement, type FC, type ReactNode, useState } from "react";
import {
	formatValue,
	type ValueFormat,
} from "@/lib/json-renderer/format-value";
import { cn, FILLED_BOX } from "@/lib/utils";
import { isExternalHttpUrl } from "../_shared/view";
import { McpMarkdownText } from "./markdown-view";

type UnknownRecord = Record<string, unknown>;

export type McpJsonNode = UnknownRecord & {
	type: string;
	children?: McpJsonNode[];
};

type RendererAction = (...args: unknown[]) => unknown;

interface RenderContext {
	data: UnknownRecord;
	actions?: Record<string, RendererAction>;
	openLink: (href: string) => void;
}

function isRecord(value: unknown): value is UnknownRecord {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function getValueByPath(value: UnknownRecord, path: string): unknown {
	const parts = path.replace(/\[(\d+)\]/g, ".$1").split(".");
	let current: unknown = value;
	for (const part of parts) {
		if (!isRecord(current) && !Array.isArray(current)) return undefined;
		current = (current as UnknownRecord)[part];
	}
	return current;
}

function stringify(value: unknown): string {
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

function humanize(value: string): string {
	return value
		.replace(/[_-]+/g, " ")
		.replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function resolveProp(value: unknown, context: RenderContext): unknown {
	if (typeof value !== "string") return value;
	if (value.startsWith("@")) return context.actions?.[value.slice(1)];
	const exact = value.match(/^\{\{(.+?)\}\}$/);
	if (exact) return getValueByPath(context.data, exact[1].trim());
	return value.replace(/\{\{(.+?)\}\}/g, (_match, path: string) => {
		const resolved = getValueByPath(context.data, path.trim());
		return resolved === undefined ? "" : String(resolved);
	});
}

function resolvedProps(
	node: McpJsonNode,
	context: RenderContext,
): UnknownRecord {
	const raw: UnknownRecord = {};
	for (const [key, value] of Object.entries(node)) {
		if (
			!["type", "children", "props", "path", "fallback", "key"].includes(key)
		) {
			raw[key] = value;
		}
	}
	if (isRecord(node.props)) Object.assign(raw, node.props);
	const resolved: UnknownRecord = {};
	for (const [key, value] of Object.entries(raw)) {
		const next = resolveProp(value, context);
		if (/^on[A-Z]/.test(key) && typeof next !== "function") continue;
		resolved[key] = next;
	}
	return resolved;
}

function domProps(props: UnknownRecord): UnknownRecord {
	const result: UnknownRecord = {};
	for (const key of [
		"className",
		"style",
		"title",
		"id",
		"role",
		"colSpan",
		"rowSpan",
		"onClick",
	]) {
		if (props[key] !== undefined) result[key] = props[key];
	}
	for (const [key, value] of Object.entries(props)) {
		if (key.startsWith("aria-") || key.startsWith("data-")) result[key] = value;
	}
	return result;
}

function scalar(value: unknown): ReactNode {
	if (value === null || value === undefined) return "";
	if (typeof value === "string" || typeof value === "number") return value;
	if (typeof value === "boolean") return value ? "Yes" : "No";
	return (
		<pre className="overflow-auto whitespace-pre-wrap text-xs">
			{stringify(value)}
		</pre>
	);
}

function normalizePoints(
	value: unknown,
	labelField = "label",
	valueField = "value",
): Array<{ key: string; label: string; sourceIndex: number; value: number }> {
	if (!Array.isArray(value)) return [];
	return value
		.map((item, index) => {
			if (typeof item === "number")
				return {
					key: `${index + 1}:${item}`,
					label: String(index + 1),
					sourceIndex: index,
					value: item,
				};
			if (!isRecord(item)) return null;
			const label = String(item[labelField] ?? item.name ?? index + 1);
			const pointValue = Number(item[valueField] ?? 0);
			return {
				key: `${label}:${pointValue}:${index}`,
				label,
				sourceIndex: index,
				value: pointValue,
			};
		})
		.filter(
			(
				item,
			): item is {
				key: string;
				label: string;
				sourceIndex: number;
				value: number;
			} => Boolean(item && Number.isFinite(item.value)),
		);
}

const CHART_COLORS = [
	"#6366f1",
	"#8b5cf6",
	"#d946ef",
	"#ec4899",
	"#f43f5e",
	"#f97316",
	"#eab308",
	"#84cc16",
	"#22c55e",
	"#14b8a6",
];
const PLATFORM_COLORS: Record<string, string> = {
	reddit: "#FF4500",
	github: "#333333",
	trustpilot: "#00B67A",
	hackernews: "#FF6600",
	x: "#1DA1F2",
	ios_appstore: "#007AFF",
	google_play: "#34A853",
	glassdoor: "#0CAA41",
	g2: "#FF492C",
	capterra: "#FF6B35",
	gmaps: "#4285F4",
};
const BADGE_FIELDS = new Set([
	"urgency",
	"severity",
	"sentiment",
	"trend",
	"status",
	"priority",
]);
const BADGE_STYLES: Record<string, string> = {
	critical: "border-red-500/30 bg-red-500/15 text-red-400",
	high: "border-orange-500/30 bg-orange-500/15 text-orange-400",
	medium: "border-yellow-500/30 bg-yellow-500/15 text-yellow-400",
	low: "border-green-500/30 bg-green-500/15 text-green-400",
};
const MAX_CHART_DIMENSION = 800;

function boundedDimension(
	value: number | undefined,
	fallback: number,
	minimum: number,
): number {
	const numeric = Number(value);
	return Math.max(
		minimum,
		Math.min(
			Number.isFinite(numeric) && numeric > 0 ? numeric : fallback,
			MAX_CHART_DIMENSION,
		),
	);
}

function seriesColor(key: string, index: number): string {
	return (
		PLATFORM_COLORS[key.toLowerCase()] ??
		CHART_COLORS[index % CHART_COLORS.length]
	);
}

/** Keep agent-authored chart paint values inert. SVG `fill="url(...)"` can make
 * a real network request even in an `allow-scripts` sandbox, so accept ordinary
 * CSS colors only and fall back to the built-in palette for everything else. */
function safeSvgPaint(value: unknown, fallback: string): string {
	if (typeof value !== "string") return fallback;
	const paint = value.trim();
	if (!paint || paint.length > 128 || /url\s*\(|[;{}<>@]/i.test(paint)) {
		return fallback;
	}
	if (/^#[\da-f]{3,8}$/i.test(paint)) return paint;
	if (/^(?:transparent|currentcolor|none|[a-z]+)$/i.test(paint)) return paint;
	if (
		/^(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch)\([-+.,%/\s\da-z]+\)$/i.test(paint)
	) {
		return paint;
	}
	return fallback;
}

const CartesianChart: FC<{
	data: unknown;
	kind: "bar" | "line" | "area";
	labelField?: string;
	valueField?: string;
	xLabel?: string;
	yLabel?: string;
	height?: number;
}> = ({ data, kind, labelField, valueField, xLabel, yLabel, height }) => {
	const points = normalizePoints(data, labelField, valueField);
	if (points.length === 0)
		return <p className="text-muted-foreground text-xs">No chart data.</p>;
	const width = 600;
	const chartHeight = boundedDimension(height, 300, 120);
	const pad = { left: 44, right: 14, top: 14, bottom: 38 };
	const innerWidth = width - pad.left - pad.right;
	const innerHeight = chartHeight - pad.top - pad.bottom;
	const min = Math.min(...points.map((point) => point.value), 0);
	const max = Math.max(...points.map((point) => point.value), 0);
	const range = Math.max(max - min, 1);
	const x = (index: number) =>
		pad.left +
		(points.length === 1
			? innerWidth / 2
			: (index / (points.length - 1)) * innerWidth);
	const y = (value: number) => pad.top + ((max - value) / range) * innerHeight;
	const zeroY = y(0);
	const line = points
		.map((point, index) => `${x(index)},${y(point.value)}`)
		.join(" ");
	return (
		<div className="overflow-x-auto">
			<svg
				viewBox={`0 0 ${width} ${chartHeight}`}
				className="min-w-[28rem] w-full"
				role="img"
				aria-label={`${humanize(kind)} chart`}
			>
				<title>{`${humanize(kind)} chart`}</title>
				<line
					x1={pad.left}
					y1={pad.top}
					x2={pad.left}
					y2={pad.top + innerHeight}
					stroke="currentColor"
					opacity="0.2"
				/>
				<line
					x1={pad.left}
					y1={zeroY}
					x2={width - pad.right}
					y2={zeroY}
					stroke="currentColor"
					opacity="0.2"
				/>
				{kind === "bar"
					? points.map((point, index) => {
							const barWidth = Math.max(8, innerWidth / points.length - 8);
							return (
								<rect
									key={point.key}
									x={pad.left + (index * innerWidth) / points.length + 4}
									y={Math.min(y(point.value), zeroY)}
									width={barWidth}
									height={Math.abs(zeroY - y(point.value))}
									fill={CHART_COLORS[0]}
								>
									<title>{`${point.label}: ${point.value}`}</title>
								</rect>
							);
						})
					: null}
				{kind === "area" ? (
					<polygon
						points={`${pad.left},${zeroY} ${line} ${width - pad.right},${zeroY}`}
						fill={CHART_COLORS[0]}
						opacity="0.2"
					/>
				) : null}
				{kind !== "bar" ? (
					<polyline
						points={line}
						fill="none"
						stroke={CHART_COLORS[0]}
						strokeWidth="3"
					/>
				) : null}
				{points.map((point, index) => (
					<g key={`label:${point.key}`}>
						<text
							x={
								kind === "bar"
									? pad.left + ((index + 0.5) * innerWidth) / points.length
									: x(index)
							}
							y={chartHeight - 16}
							textAnchor="middle"
							fontSize="11"
							fill="currentColor"
						>
							{point.label.slice(0, 12)}
						</text>
						{kind !== "bar" ? (
							<circle
								cx={x(index)}
								cy={y(point.value)}
								r="3"
								fill={CHART_COLORS[0]}
							>
								<title>{`${point.label}: ${point.value}`}</title>
							</circle>
						) : null}
					</g>
				))}
				{xLabel ? (
					<text
						x={pad.left + innerWidth / 2}
						y={chartHeight - 2}
						textAnchor="middle"
						fontSize="10"
						fill="currentColor"
					>
						{xLabel}
					</text>
				) : null}

